from taf.rfrl.l3_call.btslog.nr_btslog import NrBtsLog
from taf.rfrl.l3_call.btslog.lte_btslog import LteBtsLog
from taf.rfrl.l3_call.btslog.wcdma_btslog import WcdmaBtsLog
from taf.rfrl.l3_call.btslog.gsm_btslog import GsmBtsLog

from taf.rfrl.l3_call.btslog.exceptions import InvalidCellType


class BtsLogFactory:
    """
    Creates NrBtsLog, LteBtsLog instances
    """

    @staticmethod
    def create_btslog(duration, direction, throughput, deviation, cell_distname, cell_id, logs_path):
        """
        Creates NrBtsLog, LteBtsLog, WcdmaBtsLog, GsmBtsLog depending on cell_type retrieved from cell_distname

        :param duration: duration of data transfer, e.g. 300s
        :type duration: str
        :param throughput: Amount of data transfer throughput, e.g. '558.0 Mbits/sec'
        :type throughput: str
        :param deviation: Percentage of accepted data deviation, e.g. '10%'
        :type deviation: str
        :param direction: Transfer direction: can be downlink or uplink, e.g. 'dl' or 'ul'
        :type direction: str
        :param cell_distname: distname of cell
        :type cell_distname: str
        :param cell_id: ID of called cell from GnB (under 'NR cell ID' or 'E-UTRAN cell ID' ... field) i.e. "16385"
        :type cell_id: str
        :param logs_path: path to logs
        :type logs_path: str

        :return: Creates NrBtsLog, LteBtsLog, WcdmaBtsLog, GsmBtsLog  instance
        :rtype: BtsLog
        """
        cell_type = cell_distname.split("/")[-1]
        logfile_path = f"{logs_path}/{cell_type}_tput_msgs.log"

        if "NRCELL" in cell_type:
            return NrBtsLog(duration=duration,
                            direction=direction,
                            throughput=throughput,
                            deviation=deviation,
                            cell_id=cell_id,
                            logfile_path=logfile_path)
        if "LNCEL" in cell_type:
            return LteBtsLog(duration=duration,
                             direction=direction,
                             throughput=throughput,
                             deviation=deviation,
                             cell_id=cell_id,
                             logfile_path=logfile_path)
        if "WNCEL" in cell_type:
            return WcdmaBtsLog(duration=duration,
                               direction=direction,
                               throughput=throughput,
                               deviation=deviation,
                               cell_id=cell_id,
                               logfile_path=logfile_path)
        if "GNCEL" in cell_type:
            return GsmBtsLog(duration=duration,
                             direction=direction,
                             throughput=throughput,
                             deviation=deviation,
                             cell_id=cell_id,
                             logfile_path=logfile_path)
        else:
            raise InvalidCellType("Cell Type must be either 'NRCELL', 'LNCEL', 'GNCEL' or 'WNCEL'!")
